```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
import java.io.IOException;

public class Main {
    static int n, m;
    static int[] badMask;

    static long countSets(int idx, int forbiddenMask) {
        if (idx == n) {
            return 1;
        }

        // Opção 1: Não incluir o ingrediente idx
        long total = countSets(idx + 1, forbiddenMask);

        // Opção 2: Incluir o ingrediente idx (se não for proibido)
        if ((forbiddenMask & (1 << idx)) == 0) {
            total += countSets(idx + 1, forbiddenMask | badMask[idx]);
        }

        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        badMask = new int[n];

        for (int i = 0; i < m; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;
            st = new StringTokenizer(line);
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;

            badMask[u] |= (1 << v);
            badMask[v] |= (1 << u);
        }

        // Subtraímos 1 para desconsiderar o sanduíche vazio
        long result = countSets(0, 0) - 1;
        System.out.println(result);
    }
}
```

